import { useQuery } from "@tanstack/react-query";
import { Package, FolderOpen, TrendingUp } from "lucide-react";
import type { Product, Catalog } from "@shared/schema";

export default function Dashboard() {
  const { data: products = [], isLoading: productsLoading } = useQuery<Product[]>({
    queryKey: ["/api/products"],
  });

  const { data: catalogs = [], isLoading: catalogsLoading } = useQuery<Catalog[]>({
    queryKey: ["/api/catalogs"],
  });

  const activeProducts = products.filter(p => p.active).length;
  const totalValue = products.reduce((sum, p) => sum + (p.price || 0) * (p.stock || 0), 0);

  if (productsLoading || catalogsLoading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-64 mb-8"></div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
