          <p className="text-3xl font-bold text-gray-900" data-testid="text-total-catalogs">{catalogs.length}</p>
          <p className="text-sm text-gray-500 mt-2">Kategorien</p>
        </div>

        <div className="bg-white rounded-lg shadow p-6" data-testid="card-value">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-medium text-gray-600">Lagerwert</h2>
            <TrendingUp className="w-8 h-8 text-purple-500" />
          </div>
          <p className="text-3xl font-bold text-gray-900" data-testid="text-total-value">
            €{totalValue.toFixed(2)}
