import { useQuery, useMutation } from "@tanstack/react-query";
import { useLocation, useParams } from "wouter";
import { useForm, useFieldArray } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Plus, X, Upload, ArrowLeft, AlertCircle } from "lucide-react";
import { useState, useEffect } from "react";
import { insertProductSchema, type Product, type Catalog } from "@shared/schema";
import { apiRequest, queryClient } from "../lib/queryClient";

const dynamicFieldSchema = z.object({
  name: z.string().min(2, "Mindestens 2 Zeichen erforderlich"),
  type: z.enum(["text", "number", "boolean"]),
  value: z.string().min(1, "Erforderlich"),
}).superRefine((data, ctx) => {
  if (data.type === "number") {
    if (!/^-?\d+(\.\d+)?$/.test(data.value)) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Muss eine Zahl sein (z.B. 12 oder 12.5)",
        path: ["value"],
      });
    }
  }
  if (data.type === "boolean") {
    if (data.value !== "true" && data.value !== "false") {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Muss 'true' oder 'false' sein",
        path: ["value"],
      });
    }
  }
});

const productFormSchema = insertProductSchema.extend({
  dynamicFields: z.array(dynamicFieldSchema).default([]),
});

type ProductFormData = z.infer<typeof productFormSchema>;

export default function NewProduct() {
  const params = useParams();
  const [, navigate] = useLocation();
  const productId = params.id;
  const isEditMode = !!productId;

  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  const { data: product, isLoading: productLoading } = useQuery<Product>({
    queryKey: ["/api/products", productId],
    enabled: isEditMode,
  });

  const { data: catalogs = [] } = useQuery<Catalog[]>({
    queryKey: ["/api/catalogs"],
  });

  const form = useForm<ProductFormData>({
    resolver: zodResolver(productFormSchema),
    defaultValues: {
      name: "",
      sku: "",
      description: "",
      price: null,
      stock: null,
      catalogId: undefined,
      active: true,
      featured: false,
      dynamicFields: [],
    },
  });

  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "dynamicFields",
  });

  useEffect(() => {
    if (product) {
      form.reset({
        name: product.name,
        sku: product.sku,
        description: product.description || "",
        price: product.price,
        stock: product.stock,
        catalogId: product.catalogId || undefined,
        active: product.active,
        featured: product.featured,
        dynamicFields: (Array.isArray(product.dynamicFields) ? product.dynamicFields : []).map((f: any) => ({
          name: f.name,
          type: f.type,
          value: f.type === "boolean" ? String(f.value) : f.value,
        })),
      });
      if (product.imageUrl) {
        setImagePreview(product.imageUrl);
      }
    }
  }, [product, form]);

  const uploadMutation = useMutation({
    mutationFn: async (file: File) => {
      const formData = new FormData();
      formData.append("image", file);
      const response = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });
      if (!response.ok) throw new Error("Upload failed");
      return response.json();
    },
  });

  const createMutation = useMutation({
    mutationFn: async (data: ProductFormData) => {
      let imageUrl = imagePreview;

      if (selectedImage) {
        const uploadResult = await uploadMutation.mutateAsync(selectedImage);
        imageUrl = uploadResult.imageUrl;
      }

      const processedData = {
        ...data,
        imageUrl: imageUrl || undefined,
        dynamicFields: data.dynamicFields.map(f => ({
          name: f.name,
          type: f.type,
          value: f.type === "boolean" ? f.value === "true" : f.value,
        })),
      };

      if (isEditMode) {
        const response = await apiRequest(`/api/products/${productId}`, {
          method: "PUT",
          body: JSON.stringify(processedData),
        });
        return response.json();
      } else {
        const response = await apiRequest("/api/products", {
          method: "POST",
          body: JSON.stringify(processedData),
        });
        return response.json();
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/products"] });
      alert(isEditMode ? "Produkt erfolgreich aktualisiert!" : "Produkt erfolgreich erstellt!");
      navigate("/products");
    },
    onError: (error: Error) => {
      alert(`Fehler beim ${isEditMode ? "Aktualisieren" : "Erstellen"} des Produkts: ${error.message}`);
    },
  });

  const onImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.match(/^image\/(jpeg|jpg|png|gif|webp)$/)) {
      alert("Nur Bilddateien (JPEG, PNG, GIF, WebP) sind erlaubt!");
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      alert("Die Datei ist zu groß! Maximale Größe: 5MB");
      return;
    }

    setSelectedImage(file);
    const reader = new FileReader();
    reader.onload = () => setImagePreview(reader.result as string);
    reader.readAsDataURL(file);
  };

  const onSubmit = (data: ProductFormData) => {
    createMutation.mutate(data);
  };

  if (isEditMode && productLoading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-64 mb-8"></div>
          <div className="h-96 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b">
        <div className="max-w-7xl mx-auto px-8 py-4">
          <button
            onClick={() => navigate("/products")}
            data-testid="button-back"
            className="flex items-center text-gray-600 hover:text-gray-900"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Zurück
          </button>
        </div>
      </div>

      <div className="max-w-7xl mx-auto p-8">
        <div className="flex justify-between items-start mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900" data-testid="form-title">
              {isEditMode ? "Produkt bearbeiten" : "Neues Produkt"}
            </h1>
          </div>
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 max-w-md">
            <div className="flex items-start">
              <AlertCircle className="w-5 h-5 text-blue-600 mt-0.5 mr-2 flex-shrink-0" />
              <div className="text-sm text-blue-800">
                <p className="font-semibold mb-1">Status</p>
                <p>Keinem Katalog zugewiesen</p>
              </div>
            </div>
          </div>
        </div>

        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-8">
          <div className="bg-white rounded-lg shadow-sm border p-6 space-y-6">
            <div>
              <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-2">
                Name *
              </label>
              <input
                id="name"
                data-testid="input-name"
                {...form.register("name")}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              {form.formState.errors.name && (
                <p className="mt-1 text-sm text-red-600">{form.formState.errors.name.message}</p>
              )}
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-2">
                Beschreibung
              </label>
              <textarea
                id="description"
                data-testid="input-description"
                {...form.register("description")}
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="sku" className="block text-sm font-medium text-gray-700 mb-2">
                  SKU *
                </label>
                <input
                  id="sku"
                  data-testid="input-sku"
                  {...form.register("sku")}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                {form.formState.errors.sku && (
                  <p className="mt-1 text-sm text-red-600">{form.formState.errors.sku.message}</p>
                )}
              </div>

              <div>
                <label htmlFor="catalogId" className="block text-sm font-medium text-gray-700 mb-2">
                  Katalog
                </label>
                <select
                  id="catalogId"
                  data-testid="select-catalog"
                  {...form.register("catalogId")}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="">Kein Katalog</option>
                  {catalogs.map((catalog) => (
                    <option key={catalog.id} value={catalog.id}>
                      {catalog.name}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="price" className="block text-sm font-medium text-gray-700 mb-2">
                  Preis (€)
                </label>
                <input
                  id="price"
                  data-testid="input-price"
                  type="number"
                  step="0.01"
                  {...form.register("price", { valueAsNumber: true })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>

              <div>
                <label htmlFor="stock" className="block text-sm font-medium text-gray-700 mb-2">
                  Lagerbestand
                </label>
                <input
                  id="stock"
                  data-testid="input-stock"
                  type="number"
                  {...form.register("stock", { valueAsNumber: true })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Produktbild
              </label>
              <div className="flex items-center space-x-4">
                {imagePreview ? (
                  <div className="relative">
                    <img src={imagePreview} alt="Vorschau" className="w-32 h-32 object-cover rounded border" />
                    <button
                      type="button"
                      onClick={() => {
                        setImagePreview(null);
                        setSelectedImage(null);
                      }}
                      className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 hover:bg-red-600"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ) : (
                  <label className="cursor-pointer inline-flex items-center px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50">
                    <Upload className="w-5 h-5 mr-2" />
                    Bild hochladen
                    <input
                      type="file"
                      accept="image/*"
                      onChange={onImageSelect}
                      data-testid="input-image"
                      className="hidden"
                    />
                  </label>
                )}
              </div>
              <p className="mt-1 text-sm text-gray-500">Max. 5MB (JPEG, PNG, GIF, WebP)</p>
            </div>

            <div className="flex items-center space-x-6">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  data-testid="checkbox-active"
                  {...form.register("active")}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <span className="ml-2 text-sm text-gray-700">Produkt ist aktiv</span>
              </label>

              <label className="flex items-center">
                <input
                  type="checkbox"
                  data-testid="checkbox-featured"
                  {...form.register("featured")}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <span className="ml-2 text-sm text-gray-700">Als hervorgehoben markieren</span>
              </label>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-sm border p-6">
            <div className="flex items-center justify-between mb-6">
              <div>
                <h2 className="text-xl font-semibold text-gray-900">Dynamische Eigenschaften</h2>
                <p className="text-sm text-gray-500 mt-1">
                  Sie können beliebig benutzerdefinierte Eigenschaften hinzufügen. Diese werden als JSON am Backend gespeichert.
                </p>
              </div>
              <button
                type="button"
                data-testid="button-add-property"
                onClick={() => append({ name: "", type: "text", value: "" })}
                className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                <Plus className="w-5 h-5 mr-2" />
                Eigenschaft hinzufügen
              </button>
            </div>

            {fields.length === 0 ? (
              <div className="text-center py-8 text-gray-500">
                Keine Eigenschaften definiert. Klicken Sie auf "Eigenschaft hinzufügen" um zu beginnen.
              </div>
            ) : (
              <div className="space-y-4">
                {fields.map((field, index) => (
                  <div
                    key={field.id}
                    data-testid={`property-${index}`}
                    className="flex items-start space-x-4 p-4 bg-gray-50 rounded-lg"
                  >
                    <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-xs font-medium text-gray-700 mb-1">
                          Eigenschaftsname *
                        </label>
                        <input
                          data-testid={`input-property-name-${index}`}
                          {...form.register(`dynamicFields.${index}.name`)}
                          placeholder="z.B. Hersteller"
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                        />
                        {form.formState.errors.dynamicFields?.[index]?.name && (
                          <p className="mt-1 text-xs text-red-600">
                            {form.formState.errors.dynamicFields[index]?.name?.message}
                          </p>
                        )}
                      </div>

                      <div>
                        <label className="block text-xs font-medium text-gray-700 mb-1">
                          Typ *
                        </label>
                        <select
                          data-testid={`select-property-type-${index}`}
                          {...form.register(`dynamicFields.${index}.type`)}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                        >
                          <option value="text">Text</option>
                          <option value="number">Zahl (mit Komma)</option>
                          <option value="boolean">Ja/Nein</option>
                        </select>
                      </div>

                      <div>
                        <label className="block text-xs font-medium text-gray-700 mb-1">
                          Wert *
                        </label>
                        {form.watch(`dynamicFields.${index}.type`) === "boolean" ? (
                          <select
                            data-testid={`select-property-value-${index}`}
                            {...form.register(`dynamicFields.${index}.value`)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                          >
                            <option value="">Auswählen</option>
                            <option value="true">Ja</option>
                            <option value="false">Nein</option>
                          </select>
                        ) : (
                          <input
                            data-testid={`input-property-value-${index}`}
                            {...form.register(`dynamicFields.${index}.value`)}
                            placeholder={
                              form.watch(`dynamicFields.${index}.type`) === "number"
                                ? "z.B. 23.5"
                                : "z.B. Asus"
                            }
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                          />
                        )}
                        {form.formState.errors.dynamicFields?.[index]?.value && (
                          <p className="mt-1 text-xs text-red-600">
                            {form.formState.errors.dynamicFields[index]?.value?.message}
                          </p>
                        )}
                      </div>
                    </div>

                    <button
                      type="button"
                      data-testid={`button-remove-property-${index}`}
                      onClick={() => remove(index)}
                      className="mt-6 p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                    >
                      <X className="w-5 h-5" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="flex items-center justify-end space-x-4">
            <button
              type="button"
              data-testid="button-cancel"
              onClick={() => {
                if (confirm("Möchten Sie wirklich abbrechen? Alle ungespeicherten Änderungen gehen verloren.")) {
                  navigate("/products");
                }
              }}
              className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
            >
              Abbrechen
            </button>

            <button
              type="button"
              data-testid="button-reset"
              onClick={() => form.reset()}
              className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
            >
              Zurücksetzen
            </button>

            <button
              type="submit"
              data-testid="button-submit"
              disabled={createMutation.isPending}
              className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-400 transition-colors"
            >
              {createMutation.isPending ? "Wird gespeichert..." : "Produkt speichern"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

client/src/pages/Products.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Link } from "wouter";
import { Plus, Search } from "lucide-react";
import { useState } from "react";
import type { Product } from "@shared/schema";

export default function Products() {
  const [search, setSearch] = useState("");

  const { data: products = [], isLoading } = useQuery<Product[]>({
    queryKey: ["/api/products"],
  });

  const filteredProducts = products.filter(p => {
    if (!search) return true;
    const searchLower = search.toLowerCase();
    return (
      p.name.toLowerCase().includes(searchLower) ||
      p.sku.toLowerCase().includes(searchLower) ||
      p.description?.toLowerCase().includes(searchLower)
    );
  });

  if (isLoading) {
    return (
      <div className="p-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-64 mb-8"></div>
          <div className="h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-gray-900" data-testid="products-title">Produkte</h1>
        <Link href="/products/new">
          <a
            data-testid="button-new-product"
            className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-5 h-5 mr-2" />
            Neues Produkt
          </a>
        </Link>
      </div>

      <div className="mb-6">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input
            type="text"
            data-testid="input-search"
            placeholder="Suche nach Name, SKU oder Beschreibung..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {filteredProducts.length === 0 ? (
        <div className="bg-white rounded-lg shadow p-12 text-center">
          <p className="text-gray-500 text-lg" data-testid="text-no-products">
            {search ? "Keine Produkte gefunden" : "Keine Produkte vorhanden. Erstellen Sie Ihr erstes Produkt!"}
          </p>
        </div>
      ) : (
        <div className="bg-white rounded-lg shadow overflow-hidden">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Produkt</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">SKU</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Preis</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Lagerbestand</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Aktionen</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredProducts.map((product) => (
                <tr key={product.id} data-testid={`row-product-${product.id}`}>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      {product.imageUrl && (
                        <img
                          src={product.imageUrl}
                          alt={product.name}
                          className="w-10 h-10 rounded object-cover mr-3"
                        />
                      )}
                      <div>
                        <div className="text-sm font-medium text-gray-900">{product.name}</div>
                        {product.description && (
                          <div className="text-sm text-gray-500 truncate max-w-xs">{product.description}</div>
                        )}
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{product.sku}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {product.price ? `€${product.price.toFixed(2)}` : '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{product.stock ?? '-'}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                      product.active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                    }`}>
                      {product.active ? 'Aktiv' : 'Inaktiv'}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <Link href={`/products/${product.id}/edit`}>
                      <a data-testid={`button-edit-${product.id}`} className="text-blue-600 hover:text-blue-900">
                        Bearbeiten
                      </a>
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

client/src/app/components/catalog-edit-m.content:
import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Catalog, InsertCatalog } from '../models/catalog.model';

@Component({
  selector: 'app-catalog-edit-modal',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="modal fade" [id]="modalId" tabindex="-1" [attr.aria-labelledby]="modalId + 'Label'" aria-hidden="true" data-testid="modal-catalog-edit">
      <div class="modal-dialog">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title" [id]="modalId + 'Label'">{{ catalog ? 'Katalog bearbeiten' : 'Neuer Katalog' }}</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Schließen" data-testid="button-close-modal"></button>
          </div>
          <div class="modal-body">
            <form #catalogForm="ngForm">
              <!-- Name -->
              <div class="mb-3">
                <label for="catalogName" class="form-label">Name *</label>
                <input 
                  type="text" 
                  class="form-control" 
                  id="catalogName"
                  [(ngModel)]="formData.name" 
                  name="name"
                  required
                  minlength="2"
                  #nameField="ngModel"
                  data-testid="input-catalog-name">
                <div *ngIf="nameField.invalid && nameField.touched" class="text-danger small mt-1">
                  <div *ngIf="nameField.errors?.['required']">Name ist erforderlich</div>
                  <div *ngIf="nameField.errors?.['minlength']">Name muss mindestens 2 Zeichen lang sein</div>
                </div>
              </div>

              <!-- Description -->
              <div class="mb-3">
                <label for="catalogDescription" class="form-label">Beschreibung</label>
                <textarea 
                  class="form-control" 
                  id="catalogDescription"
                  [(ngModel)]="formData.description" 
                  name="description"
                  rows="3"
                  data-testid="input-catalog-description"></textarea>
              </div>

              <!-- Color -->
              <div class="mb-3">
                <label for="catalogColor" class="form-label">Farbe</label>
                <select 
                  class="form-select" 
                  id="catalogColor"
                  [(ngModel)]="formData.color" 
                  name="color"
                  data-testid="select-catalog-color">
                  <option value="primary">Blau (Primary)</option>
                  <option value="secondary">Grau (Secondary)</option>
                  <option value="success">Grün (Success)</option>
                  <option value="danger">Rot (Danger)</option>
                  <option value="warning">Gelb (Warning)</option>
                  <option value="info">Hellblau (Info)</option>
                  <option value="dark">Schwarz (Dark)</option>
                </select>
                <div class="mt-2">
                  <span class="badge" [ngClass]="'bg-' + formData.color">Vorschau</span>
                </div>
              </div>
            </form>
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" data-testid="button-cancel">Abbrechen</button>
            <button 
              type="button" 
              class="btn btn-primary" 
              [disabled]="catalogForm.invalid"
              (click)="onSave()"
              data-testid="button-save">
              {{ catalog ? 'Aktualisieren' : 'Erstellen' }}
            </button>
          </div>
        </div>
      </div>
    </div>
  `,
  styles: []
})
export class CatalogEditModalComponent implements OnChanges {
  @Input() catalog: Catalog | null = null;
  @Input() modalId: string = 'catalogEditModal';
  @Output() save = new EventEmitter<InsertCatalog>();

  formData: InsertCatalog = {
    name: '',
    description: '',
    color: 'primary'
  };

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['catalog'] && this.catalog) {
      this.formData = {
        name: this.catalog.name,
        description: this.catalog.description || '',
        color: this.catalog.color || 'primary'
      };
    } else if (changes['catalog'] && !this.catalog) {
      this.resetForm();
    }
  }

  onSave(): void {
    this.save.emit(this.formData);
  }

  resetForm(): void {
    this.formData = {
      name: '',
      description: '',
      color: 'primary'
    };
  }
}
